do $$
declare b jsonb;c jsonb;item jsonb;i jsonb;i2 jsonb;p jsonb;repeated jsonb;summary jsonb;bid uuid;cid uuid;payload jsonb;key uuid;failed boolean;
begin
 b:=public.billing_action('business_save','{"name":"QA Business A","address":"QA Street, Kochi","state_code":"32","registration":"regular","gstin":"32ABCDE1234F1Z5"}');bid:=(b->>'id')::uuid;
 perform set_config('billnest.qa_business_a',bid::text,true);
 c:=public.billing_action('customer_save',jsonb_build_object('business_id',bid,'name','QA Customer','address','QA Customer Road','state_code','32'));cid:=(c->>'id')::uuid;
 perform set_config('billnest.qa_customer_a',cid::text,true);
 item:=public.billing_action('item_save',jsonb_build_object('business_id',bid,'name','QA Product','kind','product','hsn_sac','8471','price_paise',100000,'tax_treatment','taxable','gst_rate_bps',1800));
 key:=gen_random_uuid();
 payload:=jsonb_build_object('business_id',bid,'customer_id',cid,'client_key',key,'issue_date',(now() at time zone 'Asia/Kolkata')::date,'due_date',(now() at time zone 'Asia/Kolkata')::date,'place_of_supply','32','lines',jsonb_build_array(jsonb_build_object('item_id',item->>'id','description','QA Product','kind','product','hsn_sac','8471','quantity_milli',2000,'price_paise',100000,'discount_bps',1000,'tax_treatment','taxable','gst_rate_bps',1800),jsonb_build_object('description','QA Service','kind','service','hsn_sac','998313','quantity_milli',1000,'price_paise',200000,'discount_bps',0,'tax_treatment','taxable','gst_rate_bps',1800)));
 i:=public.billing_action('invoice_save',payload);
 if (i->>'total_paise')::bigint<>448400 or (i->>'cgst_paise')::bigint<>34200 or (i->>'sgst_paise')::bigint<>34200 or (i->>'igst_paise')::bigint<>0 then raise exception 'TEST FAILED: invoice calculation';end if;
 repeated:=public.billing_action('invoice_save',payload);if repeated->>'id'<>i->>'id' then raise exception 'TEST FAILED: draft idempotency';end if;
 i:=public.billing_action('invoice_issue',jsonb_build_object('business_id',bid,'id',i->>'id'));
 if i->>'status'<>'issued' or length(i->>'invoice_no')>16 then raise exception 'TEST FAILED: invoice issue';end if;
 repeated:=public.billing_action('invoice_issue',jsonb_build_object('business_id',bid,'id',i->>'id'));if repeated->>'invoice_no'<>i->>'invoice_no' then raise exception 'TEST FAILED: issue idempotency';end if;
 failed:=false;begin perform public.billing_action('invoice_save',payload||jsonb_build_object('id',i->>'id'));exception when others then failed:=true;end;if not failed then raise exception 'TEST FAILED: issued invoice editable';end if;
 key:=gen_random_uuid();
 p:=public.billing_action('payment_add',jsonb_build_object('business_id',bid,'id',i->>'id','client_key',key,'amount_paise',100000,'payment_date',i->>'issue_date','method','upi'));
 repeated:=public.billing_action('payment_add',jsonb_build_object('business_id',bid,'id',i->>'id','client_key',key,'amount_paise',100000,'payment_date',i->>'issue_date','method','upi'));
 if repeated->>'id'<>p->>'id' then raise exception 'TEST FAILED: payment idempotency';end if;
 if (select paid_paise from public.invoices where id=(i->>'id')::uuid)<>100000 then raise exception 'TEST FAILED: payment counted twice';end if;
 failed:=false;begin perform public.billing_action('payment_add',jsonb_build_object('business_id',bid,'id',i->>'id','client_key',gen_random_uuid(),'amount_paise',448400,'payment_date',i->>'issue_date','method','cash'));exception when others then failed:=true;end;if not failed then raise exception 'TEST FAILED: overpayment accepted';end if;
 failed:=false;begin perform public.billing_action('invoice_cancel',jsonb_build_object('business_id',bid,'id',i->>'id','reason','QA cancellation'));exception when others then failed:=true;end;if not failed then raise exception 'TEST FAILED: paid invoice cancelled';end if;
 perform public.billing_action('payment_reverse',jsonb_build_object('business_id',bid,'id',p->>'id','reason','QA reversal'));
 if (select paid_paise from public.invoices where id=(i->>'id')::uuid)<>0 then raise exception 'TEST FAILED: reversal balance';end if;
 failed:=false;begin perform public.billing_action('payment_reverse',jsonb_build_object('business_id',bid,'id',p->>'id','reason','QA duplicate reversal'));exception when others then failed:=true;end;if not failed then raise exception 'TEST FAILED: payment reversed twice';end if;
 i2:=public.billing_action('invoice_save',payload||jsonb_build_object('client_key',gen_random_uuid(),'place_of_supply','33'));
 if (i2->>'igst_paise')::bigint<>68400 or (i2->>'cgst_paise')::bigint<>0 then raise exception 'TEST FAILED: inter-state tax';end if;
 i2:=public.billing_action('invoice_issue',jsonb_build_object('business_id',bid,'id',i2->>'id'));
 if i2->>'invoice_no'=i->>'invoice_no' then raise exception 'TEST FAILED: duplicate number';end if;
 perform public.billing_action('invoice_cancel',jsonb_build_object('business_id',bid,'id',i2->>'id','reason','QA cancellation'));
 summary:=public.billing_dashboard(bid);if (summary->>'issued_count')::integer<>1 or (summary->>'sales_month_paise')::bigint<>448400 then raise exception 'TEST FAILED: dashboard totals';end if;
 summary:=public.billing_report(bid,(now() at time zone 'Asia/Kolkata')::date,(now() at time zone 'Asia/Kolkata')::date);if (summary->'summary'->>'count')::integer<>1 then raise exception 'TEST FAILED: report count';end if;
 summary:=public.billing_invoices(bid,1,'all','QA Customer');if (summary->>'count')::integer<>2 then raise exception 'TEST FAILED: invoice search';end if;
 failed:=false;begin update public.invoices set total_paise=1 where id=(i->>'id')::uuid;exception when insufficient_privilege then failed:=true;end;if not failed then raise exception 'TEST FAILED: direct financial write allowed';end if;
end $$;
