 bid:=current_setting('billnest.qa_business_a')::uuid;
 if exists(select 1 from public.businesses where id=bid) or exists(select 1 from public.customers where business_id=bid) or exists(select 1 from public.invoices where business_id=bid) or exists(select 1 from public.payments where business_id=bid) or exists(select 1 from public.audit_events where business_id=bid) then raise exception 'TEST FAILED: cross-business read';end if;
 failed:=false;begin perform public.billing_action('customer_save',jsonb_build_object('business_id',bid,'name','Unauthorized'));exception when insufficient_privilege then failed:=true;end;if not failed then raise exception 'TEST FAILED: cross-business write';end if;
 failed:=false;begin perform public.billing_dashboard(bid);exception when insufficient_privilege then failed:=true;end;if not failed then raise exception 'TEST FAILED: cross-business dashboard';end if;
 b:=public.billing_action('business_save','{"name":"QA Business B","address":"QA B Street","state_code":"33","registration":"unregistered"}');
 failed:=false;begin perform public.billing_action('invoice_save',jsonb_build_object('business_id',b->>'id','customer_id',current_setting('billnest.qa_customer_a'),'client_key',gen_random_uuid()));exception when others then failed:=true;end;if not failed then raise exception 'TEST FAILED: cross-business customer reference';end if;
end $$;
